class Plugin:
    def __init__(self, name):
        self.name = name
    def intercept(self, chain):
        print("  [before] " + self.name)
        r = chain.proceed()
        print("  [after ] " + self.name)
        return r

class Chain:
    def __init__(self, plugins):
        self.plugins = plugins
        self.idx = 0
    def proceed(self):
        if self.idx < len(self.plugins):
            p = self.plugins[self.idx]; self.idx += 1
            return p.intercept(self)
        print("  [target] 执行 SQL")
        return "result"

